PRAGMA foreign_keys=ON;
CREATE TABLE customer_profiles(customer_id TEXT PRIMARY KEY REFERENCES ordering_customers(id),birth_date TEXT,locale TEXT NOT NULL DEFAULT 'zh-TW',marketing_opt_in INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchant_customer_profiles(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,customer_id TEXT NOT NULL REFERENCES ordering_customers(id),status TEXT NOT NULL DEFAULT 'active',total_orders INTEGER NOT NULL DEFAULT 0,total_spent_minor INTEGER NOT NULL DEFAULT 0,last_order_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,customer_id));
CREATE TABLE customer_addresses(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES ordering_customers(id),label TEXT,recipient TEXT NOT NULL,phone_encrypted TEXT NOT NULL,postal_code TEXT,address_encrypted TEXT NOT NULL,is_default INTEGER NOT NULL DEFAULT 0);
CREATE TABLE customer_tags(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,UNIQUE(merchant_id,name));
CREATE TABLE customer_tag_links(merchant_id TEXT NOT NULL,customer_id TEXT NOT NULL,tag_id TEXT NOT NULL REFERENCES customer_tags(id),PRIMARY KEY(merchant_id,customer_id,tag_id));
CREATE TABLE customer_segments(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,rules_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE customer_segment_memberships(segment_id TEXT NOT NULL REFERENCES customer_segments(id),customer_id TEXT NOT NULL,calculated_at TEXT NOT NULL,PRIMARY KEY(segment_id,customer_id));
CREATE TABLE member_levels(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,rank INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,UNIQUE(merchant_id,rank));
CREATE TABLE member_level_rules(id TEXT PRIMARY KEY,level_id TEXT NOT NULL REFERENCES member_levels(id),rule_type TEXT NOT NULL,threshold_minor INTEGER,threshold_count INTEGER,period_days INTEGER);
CREATE TABLE member_level_histories(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,customer_id TEXT NOT NULL,from_level_id TEXT,to_level_id TEXT,reason TEXT NOT NULL,effective_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE member_price_rules(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,level_id TEXT NOT NULL REFERENCES member_levels(id),product_id TEXT,variant_id TEXT,price_minor INTEGER NOT NULL,starts_at TEXT,ends_at TEXT);
CREATE TABLE customer_blacklist_entries(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,customer_id TEXT NOT NULL,reason TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,customer_id));
CREATE TABLE customer_consents(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,customer_id TEXT NOT NULL,consent_type TEXT NOT NULL,version TEXT NOT NULL,granted INTEGER NOT NULL,recorded_at TEXT NOT NULL,UNIQUE(merchant_id,customer_id,consent_type,version));
CREATE TABLE customer_activity_timeline(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,customer_id TEXT NOT NULL,event_type TEXT NOT NULL,reference_type TEXT,reference_id TEXT,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
